import { sb } from './api.js';

const app = document.querySelector('#app');
const stages = [
  ['new','Nuevo'],['contacted','Contactado'],['interested','Respondió'],['meeting_scheduled','Reunión agendada'],['meeting_completed','Reunión realizada'],
  ['proposal_sent','Propuesta'],['negotiation','Negociación'],['awaiting_payment','Esperando pago'],['won','Ganado'],['lost','Perdido']
];
const sources = ['Prospección propia','LinkedIn','Instagram','Referido','WhatsApp','Email','Llamada','Networking','Lead entregado por NextWebEC','Otro'];
const activityTypes = [['note','Nota'],['call','Llamada'],['whatsapp','WhatsApp'],['email','Email'],['meeting','Reunión'],['task','Seguimiento'],['proposal','Propuesta enviada'],['other','Otro']];
let session, profile, leads=[], services=[], profiles=[], profileNames=[], activities=[], sales=[], commissions=[], payments=[];
let page='Dashboard', query='', filters={stage:'', owner:'', source:'', service:'', after:'', before:'', followup:''}, toastTimer;
const esc = (v='') => String(v ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(n||0));
const date = v => v ? new Intl.DateTimeFormat('es-EC',{day:'2-digit',month:'short',year:'numeric'}).format(/^\d{4}-\d{2}-\d{2}$/.test(String(v))?new Date(v+'T12:00:00'):new Date(v)) : '—';
const dt = v => v ? new Intl.DateTimeFormat('es-EC',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(v)) : '—';
const isAdmin = () => profile?.role === 'admin';
const labelStage = v => stages.find(s=>s[0]===v)?.[1] || v || 'Nuevo';
const person = id => profiles.find(p=>p.id===id)?.full_name || profileNames.find(p=>p.id===id)?.full_name || 'Colaborador';
const initials = name => (name||'N').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const notify = (message,error=false) => {let el=document.querySelector('.toast'); if(!el){el=document.createElement('div');app.append(el)}el.className=`toast${error?' error':''}`;el.textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3300)};
const errText = e => e?.message || 'No se pudo completar la acción. Intenta de nuevo.';
const initialsBrand = '<span class="brand-mark">N</span>';

sb.auth.onAuthStateChange((_event,next)=>{ session=next; if(next) loadApp(); else renderLogin(); });
sb.auth.getSession().then(({data,error})=>{ if(error) renderLogin(error.message); else {session=data.session; session?loadApp():renderLogin()} });

function renderLogin(error=''){app.innerHTML=`<main class="login-wrap"><form class="login-card" id="login-form"><div class="brand">${initialsBrand}<span>NextWebEC<small>CRM comercial</small></span></div><h1>Bienvenido</h1><p>Inicia sesión con tu cuenta de NextWebEC.</p>${error?`<div class="alert">${esc(error)}</div>`:''}<div class="field"><label for="email">Correo electrónico</label><input id="email" name="email" type="email" autocomplete="username" required placeholder="nombre@empresa.com"></div><div class="field"><label for="password">Contraseña</label><input id="password" name="password" type="password" autocomplete="current-password" required placeholder="Tu contraseña"></div><button class="btn primary" style="width:100%;margin-top:10px" type="submit">Entrar</button><p class="subtext" style="text-align:center;margin-top:18px">Acceso privado para el equipo comercial</p></form></main>`;
 document.querySelector('#login-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const b=e.currentTarget.querySelector('button');b.disabled=true;b.textContent='Ingresando…';const {error}=await sb.auth.signInWithPassword({email:String(f.get('email')).trim().toLowerCase(),password:f.get('password')});if(error){renderLogin('Correo o contraseña incorrectos.');} };
}
async function loadApp(){
 if(!session)return;
 app.innerHTML='<div class="boot">Cargando NextWebEC CRM…</div>';
 try{
   const {data:pr,error:pe}=await sb.from('profiles').select('*').eq('id',session.user.id).single();if(pe)throw pe;profile=pr;if(!pr.is_active){await sb.auth.signOut();throw new Error('Esta cuenta está desactivada. Contacta al administrador.')}
   const [l,s,p,a,sa,c,pay,names]=await Promise.all([
    sb.from('leads').select('*, services(name), profiles!leads_owner_id_fkey(full_name)').is('deleted_at',null).order('updated_at',{ascending:false}),
    sb.from('services').select('*').order('name'),sb.from('profiles').select('id,full_name,email,role,is_active,created_at,phone').order('full_name'),
    sb.from('activities').select('*,profiles!activities_created_by_fkey(full_name)').order('occurred_at',{ascending:false}).limit(400),
    sb.from('sales').select('*'),sb.from('commissions').select('*'),sb.from('payments').select('*').order('paid_at',{ascending:false}),sb.rpc('get_profile_names')
   ]);
   for(const x of [l,s,p,a,sa,c,pay,names])if(x.error)throw x.error;
   leads=l.data||[];services=s.data||[];profiles=p.data||[];activities=a.data||[];sales=sa.data||[];commissions=c.data||[];payments=pay.data||[];profileNames=names.data||[];
   renderShell();
 }catch(e){app.innerHTML=`<main class="error-page"><div class="brand" style="justify-content:center">${initialsBrand} NextWebEC</div><h1>No se pudo abrir el CRM</h1><p class="subtext">${esc(errText(e))}</p><button class="btn" id="retry">Volver a intentar</button> <button class="btn" id="signout">Cerrar sesión</button></main>`;document.querySelector('#retry').onclick=loadApp;document.querySelector('#signout').onclick=()=>sb.auth.signOut()}
}
function renderShell(){const allowed=['Dashboard','Pipeline','Oportunidades','Seguimientos','Comisiones'];if(isAdmin())allowed.push('Equipo','Configuración');if(!allowed.includes(page))page='Dashboard';
const nav=[['Dashboard','◫'],['Pipeline','▦'],['Oportunidades','☷'],['Seguimientos','◷'],['Comisiones','＄'],...(isAdmin()?[['Equipo','♙'],['Configuración','⚙']]:[])];
app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">${initialsBrand}<span>NextWebEC<small>CRM comercial</small></span></div><div class="nav-label">Workspace</div><nav class="nav">${nav.map(([n,i])=>`<button data-page="${n}" class="${page===n?'active':''}"><span class="ico">${i}</span>${n}</button>`).join('')}</nav><div class="side-bottom"><div class="user-chip"><div class="avatar">${initials(profile.full_name)}</div><div class="user-meta"><b>${esc(profile.full_name)}</b><span>${isAdmin()?'Administrador':'Colaborador'}</span></div><button class="icon-btn" title="Cerrar sesión" id="logout">↪</button></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><b>${page}</b> <span class="hide-mobile">/ NextWebEC</span></div><div class="top-actions"><span class="avatar hide-mobile">${initials(profile.full_name)}</span><button class="btn primary" id="new-lead">＋ <span class="hide-mobile">Nueva oportunidad</span><span class="mobile-title">Nuevo</span></button></div></header><section class="content" id="view"></section></main><nav class="mobile-nav">${nav.slice(0,5).map(([n,i])=>`<button data-page="${n}" class="${page===n?'active':''}"><span>${i}</span>${n==='Oportunidades'?'Leads':n}</button>`).join('')}<button id="logout-mobile"><span>↪</span>Salir</button></nav><div id="modal-root"></div></div>`;
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;renderShell()});document.querySelector('#new-lead').onclick=()=>openLeadForm();document.querySelector('#logout').onclick=()=>sb.auth.signOut();document.querySelector('#logout-mobile').onclick=()=>sb.auth.signOut();renderPage();}
function visibleLeads(){return leads.filter(l=>{if(query){const q=query.toLowerCase();if(![l.company_name,l.contact_name,l.phone,l.email,l.website,l.city].some(x=>String(x||'').toLowerCase().includes(q)))return false}if(filters.stage&&l.status!==filters.stage)return false;if(filters.owner&&l.owner_id!==filters.owner)return false;if(filters.source&&l.source!==filters.source)return false;if(filters.service&&l.service_id!==filters.service)return false;if(filters.after&&new Date(l.created_at)<new Date(filters.after+'T00:00:00'))return false;if(filters.before&&new Date(l.created_at)>new Date(filters.before+'T23:59:59'))return false;if(filters.followup==='pending'&&!l.next_action_at)return false;return true})}
function setView(html){document.querySelector('#view').innerHTML=html;}
function statsCards(items){const won=sales;const ownCom=commissions.filter(c=>isAdmin()||c.executive_id===profile.id);const collected=won.reduce((n,s)=>n+Number(s.collected_amount||0),0);const pipeline=items.filter(l=>!['won','lost'].includes(l.status)).reduce((n,l)=>n+Number(l.estimated_value||0),0);const generated=ownCom.reduce((n,c)=>n+Number(c.generated_amount||0),0),pending=ownCom.reduce((n,c)=>n+Number(c.pending_amount||0),0);const metrics=[['Mis oportunidades',items.length,`${items.filter(l=>l.status==='new').length} nuevos`],['En negociación',items.filter(l=>['negotiation','awaiting_payment'].includes(l.status)).length,'Oportunidades activas'],['Ventas cerradas',money(collected),`${won.length} proyectos ganados`],['Comisión pendiente',money(pending),`${money(generated)} generada`]];if(isAdmin())metrics[0]=['Oportunidades totales',items.length,`${profiles.filter(p=>p.is_active&&p.role==='executive').length} colaboradores activos`];return `<div class="grid stats">${metrics.map(([a,b,c])=>`<article class="stat"><div class="stat-label">${a}</div><div class="stat-value">${b}</div><div class="stat-note">${c}</div></article>`).join('')}</div>`}
function dashboardStats(items){const ownCom=commissions.filter(c=>isAdmin()||c.executive_id===profile.id);const pipe=items.filter(l=>!['won','lost'].includes(l.status)).reduce((n,l)=>n+Number(l.estimated_value||0),0);const closed=sales.reduce((n,s)=>n+Number(s.total_value||0),0),collected=sales.reduce((n,s)=>n+Number(s.collected_amount||0),0);const metrics=isAdmin()?[['Oportunidades totales',items.length,'En todos los vendedores'],['Vendedores activos',profiles.filter(p=>p.role==='executive'&&p.is_active).length,'Equipo comercial'],['Valor del pipeline',money(pipe),'Oportunidades activas'],['Facturación cerrada',money(closed),'Proyectos ganados'],['Dinero cobrado',money(collected),'Ingresos confirmados'],['Comisiones generadas',money(ownCom.reduce((n,c)=>n+Number(c.generated_amount||0),0)),'Al 40% de lo cobrado'],['Comisiones pagadas',money(ownCom.reduce((n,c)=>n+Number(c.paid_amount||0),0)),'Confirmadas por administración'],['Comisiones pendientes',money(ownCom.reduce((n,c)=>n+Number(c.pending_amount||0),0)),'Por pagar']]:[['Mis oportunidades',items.length,'Prospectos registrados'],['Nuevos leads',items.filter(l=>l.status==='new').length,'Por contactar'],['En negociación',items.filter(l=>['negotiation','awaiting_payment'].includes(l.status)).length,'Oportunidades activas'],['Propuestas enviadas',items.filter(l=>l.status==='proposal_sent').length,'En evaluación'],['Ganados',items.filter(l=>l.status==='won').length,'Proyectos cerrados'],['Perdidos',items.filter(l=>l.status==='lost').length,'Oportunidades cerradas'],['Valor del pipeline',money(pipe),'Oportunidades activas'],['Ventas cerradas',money(closed),`${money(collected)} cobrados`],['Comisión generada',money(ownCom.reduce((n,c)=>n+Number(c.generated_amount||0),0)),'Por cobros recibidos'],['Comisión pendiente',money(ownCom.reduce((n,c)=>n+Number(c.pending_amount||0),0)),'Por pagar']];return `<div class="grid stats">${metrics.map(([a,b,c])=>`<article class="stat"><div class="stat-label">${a}</div><div class="stat-value">${b}</div><div class="stat-note">${c}</div></article>`).join('')}</div>`}
function renderPage(){const items=visibleLeads();if(page==='Dashboard')renderDashboard(items);else if(page==='Pipeline')renderPipeline(items);else if(page==='Oportunidades')renderOpportunities(items);else if(page==='Seguimientos')renderFollowups(items);else if(page==='Comisiones')renderCommissions();else if(page==='Equipo')renderTeam();else if(page==='Configuración')renderSettings();}
function renderDashboard(items){const due=items.filter(l=>l.next_action_at&&new Date(l.next_action_at)<new Date()&&!['won','lost'].includes(l.status)).sort((a,b)=>new Date(a.next_action_at)-new Date(b.next_action_at)).slice(0,6);setView(`<div class="page-head"><div><h1>Buenos días, ${esc(profile.full_name.split(' ')[0])}</h1><p>Un vistazo claro a tus oportunidades comerciales.</p></div><button class="btn" data-page="Seguimientos">Ver seguimientos →</button></div>${dashboardStats(items)}<div class="grid" style="grid-template-columns:minmax(0,1.5fr) minmax(260px,1fr)"><section class="panel"><div class="panel-head"><h2>Seguimientos pendientes</h2><button class="btn small" data-page="Seguimientos">Ver todos</button></div>${due.length?due.map(l=>`<div class="rank-row" style="grid-template-columns:1.5fr 1fr auto;cursor:pointer" data-open="${l.id}"><div><b>${esc(l.company_name)}</b><span class="subtext">${esc(l.contact_name)}</span></div><span class="followup">${esc(l.next_action||'Seguimiento')}<span class="subtext">${date(l.next_action_at)}</span></span><span class="badge ${new Date(l.next_action_at)<new Date()?'red':'blue'}">${new Date(l.next_action_at)<new Date()?'Vencido':'Próximo'}</span></div>`).join(''):`<div class="empty"><strong>Todo al día</strong>No tienes seguimientos vencidos.</div>`}</section><section class="panel"><div class="panel-head"><h2>Resumen del pipeline</h2></div>${stages.slice(0,7).map(([key,name])=>{const n=items.filter(x=>x.status===key).length;return `<div style="display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #eff1f4;font-size:11px"><span>${name}</span><b>${n}</b></div>`}).join('')}</section>${isAdmin()?`<section class="panel" style="grid-column:1/-1"><div class="panel-head"><h2>Actividad del equipo</h2><span class="subtext">Resumen por colaborador</span></div>${renderRanking()}</section>`:''}</div>`);wireCommon();document.querySelectorAll('[data-open]').forEach(el=>el.onclick=()=>openDetail(el.dataset.open));}
function filterBar(){return `<div class="toolbar"><div class="search"><input id="search" placeholder="Buscar empresa, contacto, teléfono o email…" value="${esc(query)}"></div><select id="filter-stage"><option value="">Todos los estados</option>${stages.map(([k,v])=>`<option value="${k}" ${filters.stage===k?'selected':''}>${v}</option>`).join('')}</select>${isAdmin()?`<select id="filter-owner"><option value="">Todos los vendedores</option>${profiles.filter(p=>p.role==='executive').map(p=>`<option value="${p.id}" ${filters.owner===p.id?'selected':''}>${esc(p.full_name)}</option>`).join('')}</select>`:''}<select id="filter-source"><option value="">Todas las fuentes</option>${sources.map(x=>`<option ${filters.source===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="filter-service"><option value="">Todos los servicios</option>${services.map(x=>`<option value="${x.id}" ${filters.service===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><select id="filter-followup"><option value="">Seguimientos</option><option value="pending" ${filters.followup==='pending'?'selected':''}>Con seguimiento pendiente</option></select><input id="filter-after" aria-label="Desde" type="date" value="${filters.after}"><input id="filter-before" aria-label="Hasta" type="date" value="${filters.before}"></div>`}
function rowLead(l){return `<tr data-open="${l.id}"><td>${date(l.created_at)}</td><td><span class="company">${esc(l.company_name)}</span><span class="subtext">${esc(l.services?.name||'Sin servicio')}</span></td><td>${esc(l.contact_name)}</td><td>${esc(l.phone||'—')}</td><td>${esc(l.profiles?.full_name||person(l.owner_id))}</td><td><span class="badge ${l.status==='won'?'green':l.status==='lost'?'red':'blue'}">${labelStage(l.status)}</span></td><td>${money(l.estimated_value)}</td><td>${date(l.next_action_at)}</td><td>${dt(l.updated_at)}</td></tr>`}
function mobileLead(l){return `<article class="mobile-lead" data-open="${l.id}"><div class="mobile-lead-head"><div><h3>${esc(l.company_name)}</h3><p>${esc(l.contact_name)} · ${esc(l.phone||'Sin teléfono')}</p></div><span class="badge ${l.status==='won'?'green':l.status==='lost'?'red':'blue'}">${labelStage(l.status)}</span></div><div class="mobile-lead-foot"><span>${money(l.estimated_value)} · ${esc(l.profiles?.full_name||person(l.owner_id))}</span><span>${l.next_action_at?date(l.next_action_at):'Sin seguimiento'}</span></div></article>`}
function renderOpportunities(items){setView(`<div class="page-head"><div><h1>Oportunidades</h1><p>Prospectos, etapas y próximos pasos en un solo lugar.</p></div>${isAdmin()?`<button class="btn" id="export-csv">↓ Exportar CSV</button>`:''}</div>${filterBar()}<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Empresa</th><th>Contacto</th><th>Teléfono</th><th>Vendedor</th><th>Estado</th><th>Valor</th><th>Seguimiento</th><th>Última actividad</th></tr></thead><tbody>${items.map(rowLead).join('')}</tbody></table></div><div class="mobile-cards">${items.map(mobileLead).join('')}</div>${items.length?'':`<div class="empty"><strong>Aún no hay oportunidades</strong>Registra tu primer prospecto para empezar.</div>`}</section>`);wireCommon();document.querySelectorAll('[data-open]').forEach(el=>el.onclick=()=>openDetail(el.dataset.open));document.querySelector('#export-csv')?.addEventListener('click',exportCsv)}
function renderPipeline(items){setView(`<div class="page-head"><div><h1>Pipeline</h1><p>Arrastra una oportunidad a otra etapa para actualizarla.</p></div><button class="btn" data-page="Oportunidades">☷ Vista tabla</button></div>${filterBar()}<div class="kanban">${stages.map(([key,name])=>{const group=items.filter(l=>l.status===key);return `<section class="kanban-col" data-stage="${key}"><div class="kanban-title"><span>${name}</span><span>${group.length}</span></div>${group.map(l=>`<article class="lead-card" draggable="true" data-lead="${l.id}" data-open="${l.id}"><h3>${esc(l.company_name)}</h3><p>${esc(l.contact_name)}</p><div class="card-foot"><span>${money(l.estimated_value)}</span><span>${l.next_action_at?date(l.next_action_at):'—'}</span></div></article>`).join('')}</section>`}).join('')}</div>`);wireCommon();document.querySelectorAll('[data-open]').forEach(el=>el.onclick=()=>{if(!window.__dragging)openDetail(el.dataset.open)});document.querySelectorAll('.lead-card').forEach(card=>{card.ondragstart=e=>{window.__dragging=true;e.dataTransfer.setData('text/plain',card.dataset.lead);card.classList.add('dragging')};card.ondragend=()=>{card.classList.remove('dragging');setTimeout(()=>window.__dragging=false,0)}});document.querySelectorAll('.kanban-col').forEach(col=>{col.ondragover=e=>e.preventDefault();col.ondrop=async e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');const lead=leads.find(l=>l.id===id);if(lead&&lead.status!==col.dataset.stage)await changeStage(lead,col.dataset.stage)}})}
function renderFollowups(items){const now=new Date(),rows=items.filter(l=>l.next_action_at&&!['won','lost'].includes(l.status)).sort((a,b)=>new Date(a.next_action_at)-new Date(b.next_action_at));const overdue=rows.filter(l=>new Date(l.next_action_at)<now),today=rows.filter(l=>new Date(l.next_action_at).toDateString()===now.toDateString()),upcoming=rows.filter(l=>new Date(l.next_action_at)>now&&!today.includes(l));setView(`<div class="page-head"><div><h1>Seguimientos</h1><p>Prioriza las próximas conversaciones y tareas.</p></div></div>${statsCards(items)}${[['Vencidos',overdue],['Para hoy',today],['Próximos',upcoming]].map(([title,list])=>`<section class="panel" style="margin-bottom:14px"><div class="panel-head"><h2>${title}</h2><span class="badge ${title==='Vencidos'?'red':'blue'}">${list.length}</span></div>${list.length?list.map(l=>`<div class="rank-row" style="grid-template-columns:1.3fr 1fr 1fr auto;cursor:pointer" data-open="${l.id}"><div><b>${esc(l.company_name)}</b><span class="subtext">${esc(l.contact_name)}</span></div><span>${esc(l.next_action||'Seguimiento')}</span><span>${dt(l.next_action_at)}</span><span class="badge">${labelStage(l.status)}</span></div>`).join(''):`<div class="empty">Sin seguimientos en esta sección.</div>`}</section>`).join('')}`);wireCommon();document.querySelectorAll('[data-open]').forEach(el=>el.onclick=()=>openDetail(el.dataset.open));}
function renderCommissions(){const rows=commissions.filter(c=>isAdmin()||c.executive_id===profile.id);const gen=rows.reduce((a,c)=>a+Number(c.generated_amount||0),0),paid=rows.reduce((a,c)=>a+Number(c.paid_amount||0),0),pending=rows.reduce((a,c)=>a+Number(c.pending_amount||0),0);setView(`<div class="page-head"><div><h1>Comisiones</h1><p>Se calculan al 40% del dinero efectivamente recibido por NextWebEC.</p></div></div><div class="grid stats"><article class="stat"><div class="stat-label">Comisión generada</div><div class="stat-value">${money(gen)}</div></article><article class="stat"><div class="stat-label">Comisión pagada</div><div class="stat-value">${money(paid)}</div></article><article class="stat"><div class="stat-label">Pendiente de pago</div><div class="stat-value">${money(pending)}</div></article><article class="stat"><div class="stat-label">Tasa aplicada</div><div class="stat-value">40%</div></article></div><section class="panel"><div class="table-wrap"><table class="data-table" style="display:table;min-width:580px"><thead><tr><th>Proyecto</th>${isAdmin()?'<th>Colaborador</th>':''}<th>Valor vendido</th><th>Cobrado</th><th>Generada</th><th>Pagada</th><th>Pendiente</th>${isAdmin()?'<th></th>':''}</tr></thead><tbody>${rows.map(c=>{const sale=sales.find(s=>s.id===c.sale_id),lead=leads.find(l=>l.id===sale?.lead_id);return `<tr><td><b>${esc(lead?.company_name||'Proyecto')}</b><span class="subtext">${date(sale?.signed_at)}</span></td>${isAdmin()?`<td>${esc(person(c.executive_id))}</td>`:''}<td>${money(sale?.total_value)}</td><td>${money(sale?.collected_amount)}</td><td>${money(c.generated_amount)}</td><td>${money(c.paid_amount)}</td><td><b>${money(c.pending_amount)}</b></td>${isAdmin()?`<td>${Number(c.pending_amount)>0?`<button class="btn small" data-pay-commission="${c.id}">Registrar pago</button>`:''}</td>`:''}</tr>`}).join('')}</tbody></table></div>${rows.length?'':`<div class="empty"><strong>Todavía no hay comisiones</strong>Al registrar cobros de proyectos ganados, el cálculo aparecerá aquí.</div>`}</section>`);document.querySelectorAll('[data-pay-commission]').forEach(b=>b.onclick=()=>openCommissionPayment(b.dataset.payCommission));}
function renderRanking(){const execs=profiles.filter(p=>p.role==='executive');return `<div class="ranking"><div class="rank-row head"><span>Colaborador</span><span>Oportunidades</span><span>Reuniones</span><span>Propuestas</span><span>Ventas</span><span>Vendido</span><span>Cobrado</span></div>${execs.map(p=>{const own=leads.filter(l=>l.owner_id===p.id),ownSales=sales.filter(s=>s.executive_id===p.id);return `<div class="rank-row"><b>${esc(p.full_name)}</b><span>${own.length}</span><span>${own.filter(l=>['meeting_scheduled','meeting_completed'].includes(l.status)).length}</span><span>${own.filter(l=>l.status==='proposal_sent').length}</span><span>${own.filter(l=>l.status==='won').length}</span><span>${money(ownSales.reduce((n,s)=>n+Number(s.total_value),0))}</span><span>${money(ownSales.reduce((n,s)=>n+Number(s.collected_amount),0))}</span></div>`}).join('')||'<div class="empty">Agrega colaboradores para ver el resumen.</div>'}</div>`}
function renderTeam(){const team=profiles.filter(p=>p.role==='executive');setView(`<div class="page-head"><div><h1>Equipo</h1><p>Gestiona el acceso y consulta resultados de los colaboradores.</p></div><button class="btn primary" id="invite-user">＋ Crear usuario</button></div><section class="panel"><div class="table-wrap"><table class="data-table" style="display:table;min-width:600px"><thead><tr><th>Colaborador</th><th>Oportunidades</th><th>Ventas</th><th>Cobrado</th><th>Estado</th><th></th></tr></thead><tbody>${team.map(p=>{const own=leads.filter(l=>l.owner_id===p.id),sv=sales.filter(s=>s.executive_id===p.id);return `<tr><td><b>${esc(p.full_name)}</b><span class="subtext">${esc(p.email)}</span></td><td>${own.length}</td><td>${money(sv.reduce((n,s)=>n+Number(s.total_value||0),0))}</td><td>${money(sv.reduce((n,s)=>n+Number(s.collected_amount||0),0))}</td><td><span class="badge ${p.is_active?'green':'red'}">${p.is_active?'Activo':'Inactivo'}</span></td><td><button class="btn small" data-toggle-user="${p.id}" data-active="${p.is_active}">${p.is_active?'Desactivar':'Reactivar'}</button></td></tr>`}).join('')}</tbody></table></div>${team.length?'':`<div class="empty"><strong>El equipo comienza aquí</strong>Crea la primera cuenta para un colaborador.</div>`}</section>`);document.querySelector('#invite-user').onclick=openInvite;document.querySelectorAll('[data-toggle-user]').forEach(b=>b.onclick=()=>toggleUser(b.dataset.toggleUser,b.dataset.active==='true'));}
function renderSettings(){setView(`<div class="page-head"><div><h1>Configuración</h1><p>Catálogo de servicios, respaldo local y comisión del equipo.</p></div><a class="btn" href="/api/admin/backup">Descargar respaldo SQLite</a></div><section class="panel"><div class="panel-head"><h2>Servicios</h2><button class="btn primary small" id="new-service">＋ Agregar servicio</button></div><div class="table-wrap"><table class="data-table" style="display:table;min-width:450px"><thead><tr><th>Servicio</th><th>Precio referencial</th><th>Estado</th><th></th></tr></thead><tbody>${services.map(s=>`<tr><td><b>${esc(s.name)}</b></td><td>${money(s.default_price)}</td><td><span class="badge ${s.is_active?'green':'red'}">${s.is_active?'Activo':'Inactivo'}</span></td><td><button class="btn small" data-edit-service="${s.id}">Editar</button> <button class="btn small" data-toggle-service="${s.id}" data-active="${s.is_active}">${s.is_active?'Desactivar':'Activar'}</button></td></tr>`).join('')}</tbody></table></div><div class="notice" style="margin-top:18px">La tasa de comisión es del 40% de cada cobro confirmado. Descarga respaldos desde aquí y guárdalos fuera del servidor.</div></section>`);document.querySelector('#new-service').onclick=openService;document.querySelectorAll('[data-edit-service]').forEach(b=>b.onclick=()=>editService(b.dataset.editService));document.querySelectorAll('[data-toggle-service]').forEach(b=>b.onclick=()=>toggleService(b.dataset.toggleService,b.dataset.active==='true'));}
function wireCommon(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;renderShell()});const s=document.querySelector('#search');if(s)s.oninput=()=>{query=s.value;const pos=s.selectionStart;renderPage();const n=document.querySelector('#search');n.focus();n.setSelectionRange(pos,pos)};for(const [id,key] of [['filter-stage','stage'],['filter-owner','owner'],['filter-source','source'],['filter-service','service'],['filter-followup','followup'],['filter-after','after'],['filter-before','before']])document.querySelector('#'+id)?.addEventListener('change',e=>{filters[key]=e.target.value;renderPage()});}
function modal(title,body,{wide=false,submitLabel='Guardar',onSubmit}={}){const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}"><header class="modal-head"><h2>${title}</h2><button class="icon-btn" data-close>✕</button></header><form id="modal-form"><div class="modal-body">${body}</div><footer class="modal-foot"><button class="btn" type="button" data-close>Cancelar</button>${onSubmit?`<button class="btn primary" id="modal-submit">${submitLabel}</button>`:''}</footer></form></section></div>`;root.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>root.innerHTML='');root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''};const form=root.querySelector('#modal-form');if(onSubmit)form.onsubmit=async e=>{e.preventDefault();const b=root.querySelector('#modal-submit');b.disabled=true;b.textContent='Guardando…';try{await onSubmit(new FormData(form));root.innerHTML=''}catch(err){notify(errText(err),true);b.disabled=false;b.textContent=submitLabel}};return root;}
function optionsServices(selected=''){return `<option value="">Sin especificar</option>${services.filter(s=>s.is_active).map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${esc(s.name)}</option>`).join('')}`}
function openLeadForm(){const root=modal('Nueva oportunidad',`<p class="subtext">Registra lo esencial ahora. Podrás completar el resto después.</p><div id="duplicate-result"></div><div class="form-grid"><div class="field"><label>Empresa *</label><input name="company_name" required maxlength="160" autocomplete="organization"></div><div class="field"><label>Nombre del contacto *</label><input name="contact_name" required maxlength="160" autocomplete="name"></div><div class="field"><label>Teléfono</label><input name="phone" inputmode="tel" autocomplete="tel" placeholder="+593 99 123 4567"></div><div class="field"><label>Email</label><input name="email" type="email" autocomplete="email" placeholder="contacto@empresa.com"></div><div class="field"><label>Sitio web</label><input name="website" type="text" placeholder="empresa.com"></div><div class="field"><label>Servicio de interés</label><select name="service_id">${optionsServices()}</select></div><div class="field"><label>Valor estimado (USD)</label><input name="estimated_value" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Fuente</label><select name="source">${sources.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div class="field"><label>Origen del lead</label><select name="lead_origin"><option value="self_generated">Prospección propia</option><option value="company_assigned">Lead asignado por NextWebEC</option><option value="referral">Referido</option><option value="other">Otro</option></select></div><div class="field span-2"><label>Notas iniciales</label><textarea name="notes" maxlength="2000" placeholder="Contexto importante para el primer contacto…"></textarea></div></div><div class="notice">El primer registro conserva automáticamente autor, hora e ID. Si el sistema encuentra una coincidencia, mostrará el propietario registrado.</div>`,{submitLabel:'Revisar y guardar',onSubmit:async f=>{
 const phone=String(f.get('phone')||'').replace(/[^+\d]/g,'');const email=String(f.get('email')||'').trim().toLowerCase();const website=String(f.get('website')||'').trim();let normalizedWebsite=website?(/^https?:\/\//i.test(website)?website:'https://'+website):null;if(normalizedWebsite){try{normalizedWebsite=new URL(normalizedWebsite).origin}catch{throw new Error('Ingresa un sitio web válido.')}}const {data,error}=await sb.rpc('create_lead_if_unique',{p_company:String(f.get('company_name')).trim(),p_contact:String(f.get('contact_name')).trim(),p_phone:phone||null,p_email:email||null,p_website:normalizedWebsite,p_service_id:f.get('service_id')||null,p_estimated_value:Number(f.get('estimated_value')||0),p_source:f.get('source'),p_lead_origin:f.get('lead_origin'),p_notes:String(f.get('notes')||'').trim()||null});if(error)throw error;const outcome=data?.[0];if(!outcome?.created){const box=document.querySelector('#duplicate-result');box.innerHTML=`<div class="alert"><b>Este prospecto ya se encuentra registrado.</b><br>${esc(outcome?.company_name)} · Responsable: ${esc(outcome?.owner_name)} · ${date(outcome?.created_at)} · ${esc(labelStage(outcome?.status))}</div>`;throw new Error('Revisa el registro existente antes de continuar.')};await loadApp();notify('Oportunidad registrada con éxito.');
 }});const f=root.querySelector('#modal-form');let timer;for(const name of ['phone','email','website','company_name','contact_name'])f.elements[name].addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(async()=>{const form=new FormData(f);if(!form.get('phone')&&!form.get('email')&&!form.get('company_name'))return;const result=document.querySelector('#duplicate-result');if(!result)return;const {data,error}=await sb.rpc('check_lead_duplicate',{p_phone:String(form.get('phone')||'').replace(/[^+\d]/g,'' )||null,p_email:String(form.get('email')||'').trim().toLowerCase()||null,p_website:(String(form.get('website')||'').trim()?(/^https?:\/\//i.test(String(form.get('website')).trim())?String(form.get('website')).trim():'https://'+String(form.get('website')).trim()):null),p_company:String(form.get('company_name')||'').trim(),p_contact:String(form.get('contact_name')||'').trim()});if(!error&&data?.length){const d=data[0];result.innerHTML=`<div class="alert"><b>Este prospecto ya se encuentra registrado.</b><br>${esc(d.company_name)} · Responsable: ${esc(d.owner_name)} · ${date(d.created_at)} · ${esc(labelStage(d.status))}</div>`}else result.innerHTML=''},400)});}
function renderHistory(hist) {
  if (!hist.length) return '<div class="empty">Aún no hay cambios registrados.</div>';
  const fields = [['status','Estado'],['estimated_value','Valor estimado'],['owner_id','Responsable'],['company_name','Empresa'],['contact_name','Contacto'],['phone','Teléfono'],['email','Email'],['website','Sitio web'],['job_title','Cargo'],['city','Ciudad'],['country','País'],['service_id','Servicio'],['source','Fuente'],['lead_origin','Origen'],['next_action','Próxima acción'],['next_action_at','Seguimiento'],['notes','Notas'],['is_archived','Archivada']];
  const value = (key, v) => v == null || v === '' ? '—' : key === 'status' ? labelStage(v) : key === 'owner_id' ? person(v) : key === 'service_id' ? (services.find(s => s.id === v)?.name || 'Sin especificar') : key === 'estimated_value' ? money(v) : key === 'next_action_at' ? dt(v) : key === 'is_archived' ? (v ? 'Sí' : 'No') : String(v);
  const item = h => {
    const old = h.before_data || {}, next = h.after_data || {};
    const changed = fields.filter(([key]) => old[key] !== next[key]);
    let title = 'Datos actualizados';
    if (h.operation === 'INSERT') title = 'Oportunidad creada';
    else if (changed.length === 1) {
      const [key, label] = changed[0];
      title = key === 'status' ? `${labelStage(old.status)} → ${labelStage(next.status)}` : key === 'owner_id' ? `Responsable: ${person(next.owner_id)}` : key === 'is_archived' ? (next.is_archived ? 'Oportunidad archivada' : 'Oportunidad restaurada') : `${label} actualizado`;
    } else if (changed.length > 1) title = `${changed.length} datos actualizados`;
    const details = h.operation !== 'INSERT' && changed.length ? `<details class="history-details"><summary>Ver cambios</summary><ul>${changed.map(([key,label]) => `<li><strong>${esc(label)}</strong>: ${esc(value(key,old[key]))} → ${esc(value(key,next[key]))}</li>`).join('')}</ul></details>` : '';
    return `<div class="timeline-item"><b>${esc(title)}</b><p>${esc(person(h.actor_id))} · <time>${dt(h.created_at)}</time></p>${details}</div>`;
  };
  return `<div class="timeline">${hist.slice(0,5).map(item).join('')}</div>${hist.length > 5 ? `<details class="history-more"><summary>Ver ${hist.length - 5} cambios anteriores</summary><div class="timeline">${hist.slice(5).map(item).join('')}</div></details>` : ''}`;
}

async function openDetail(id){const lead=leads.find(l=>l.id===id);if(!lead)return;const [actRes,histRes,saleRes]=await Promise.all([sb.from('activities').select('*,profiles!activities_created_by_fkey(full_name)').eq('lead_id',id).order('occurred_at',{ascending:false}),sb.from('lead_audit_log').select('*').eq('lead_id',id).order('created_at',{ascending:false}).limit(40),sb.from('sales').select('*').eq('lead_id',id).maybeSingle()]);const acts=actRes.data||[],hist=histRes.data||[],sale=saleRes.data;const leadPayments=sale?payments.filter(p=>p.sale_id===sale.id):[];const root=modal(esc(lead.company_name),`<div class="detail-grid"><div><h2 class="detail-title">${esc(lead.contact_name)}</h2><p class="subtext">${esc(lead.services?.name||'Sin servicio')} · ${money(sale?.total_value||lead.estimated_value)}</p><div class="field"><label>Estado de oportunidad</label><select id="detail-stage" ${!isAdmin()&&lead.owner_id!==profile.id?'disabled':''}>${stages.map(([k,v])=>`<option value="${k}" ${lead.status===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="detail-facts"><div class="fact"><label>Teléfono</label><b>${esc(lead.phone||'—')}</b></div><div class="fact"><label>Email</label><b>${esc(lead.email||'—')}</b></div><div class="fact"><label>Valor estimado</label><b>${money(lead.estimated_value)}</b></div><div class="fact"><label>Propietario actual</label><b>${esc(person(lead.owner_id))}</b></div></div><section class="panel" style="margin-top:18px;padding:14px"><div class="panel-head"><h2>Registro de propiedad</h2></div><div class="fact"><label>Registrado por</label><b>${esc(person(lead.created_by))}</b></div><div class="fact" style="margin-top:10px"><label>Fecha y hora</label><b>${dt(lead.created_at)}</b></div><div class="fact" style="margin-top:10px"><label>ID</label><b style="font-size:10px;word-break:break-all">${esc(lead.id)}</b></div><button type="button" class="btn small" id="edit-lead" style="margin-top:12px">Editar oportunidad</button>${isAdmin()?`<button type="button" class="btn danger small" id="archive-lead" style="margin-top:12px">Archivar oportunidad</button><div class="field"><label>Reasignar propietario</label><select id="reassign">${profiles.filter(p=>p.role==='executive'&&p.is_active).map(p=>`<option value="${p.id}" ${lead.owner_id===p.id?'selected':''}>${esc(p.full_name)}</option>`).join('')}</select></div>`:''}</section>${sale?`<section class="panel" style="margin-top:12px;padding:14px"><div class="panel-head"><h2>Pagos y comisión</h2>${isAdmin()?`<button type="button" class="btn small" id="add-payment">＋ Cobro</button>`:''}</div><div class="detail-facts"><div class="fact"><label>Valor final</label><b>${money(sale.total_value)}</b></div><div class="fact"><label>Cobrado</label><b>${money(sale.collected_amount)}</b></div><div class="fact"><label>Saldo</label><b>${money(sale.pending_balance)}</b></div><div class="fact"><label>Comisión al 40%</label><b>${money(commissions.find(c=>c.sale_id===sale.id)?.generated_amount)}</b></div></div>${leadPayments.length?`<div style="margin-top:14px"><b style="font-size:11px">Cobros registrados</b>${leadPayments.map(p=>`<div style="display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #eff1f4;font-size:11px"><span>${date(p.paid_at)} · ${esc(p.payment_method||'Pago')}</span><b>${money(p.amount)}</b></div>`).join('')}</div>`:''}</section>`:''}</div><div><section class="panel"><div class="panel-head"><h2>Actividad</h2><button type="button" class="btn small" id="add-activity">＋ Registrar</button></div>${acts.length?`<div class="timeline">${acts.map(a=>`<div class="timeline-item"><b>${esc(activityTypes.find(t=>t[0]===a.type)?.[1]||a.type)} · ${esc(a.profiles?.full_name||'Equipo')}</b><p>${esc(a.subject)}${a.body?`<br>${esc(a.body)}`:''}</p><time>${dt(a.occurred_at)}</time></div>`).join('')}</div>`:'<div class="empty">Aún no hay actividad registrada.</div>'}</section><section class="panel" style="margin-top:12px"><div class="panel-head"><h2>Historial</h2></div>${renderHistory(hist)}</section></div></div>`,{wide:true});root.querySelector('#detail-stage').onchange=e=>changeStage(lead,e.target.value);root.querySelector('#add-activity').onclick=()=>openActivity(lead);root.querySelector('#edit-lead').onclick=()=>openEditLead(lead);root.querySelector('#reassign')?.addEventListener('change',async e=>{if(e.target.value===lead.owner_id)return;const {error}=await sb.from('leads').update({owner_id:e.target.value}).eq('id',lead.id);if(error)notify(errText(error),true);else{notify('Propietario actualizado.');await loadApp();openDetail(lead.id)}});root.querySelector('#add-payment')?.addEventListener('click',()=>openPayment(sale));root.querySelector('#archive-lead')?.addEventListener('click',()=>archiveLead(lead));}
function openEditLead(lead){modal('Editar oportunidad',`<div class="form-grid"><div class="field"><label>Empresa *</label><input name="company_name" required value="${esc(lead.company_name)}"></div><div class="field"><label>Contacto *</label><input name="contact_name" required value="${esc(lead.contact_name)}"></div><div class="field"><label>Cargo</label><input name="job_title" value="${esc(lead.job_title||'')}"></div><div class="field"><label>Teléfono</label><input name="phone" value="${esc(lead.phone||'')}"></div><div class="field"><label>WhatsApp</label><input name="whatsapp" value="${esc(lead.whatsapp||'')}"></div><div class="field"><label>Email</label><input name="email" type="email" value="${esc(lead.email||'')}"></div><div class="field"><label>Sitio web</label><input name="website" value="${esc(lead.website||'')}"></div><div class="field"><label>Ciudad</label><input name="city" value="${esc(lead.city||'')}"></div><div class="field"><label>País</label><input name="country" value="${esc(lead.country||'Ecuador')}"></div><div class="field"><label>Servicio</label><select name="service_id">${optionsServices(lead.service_id)}</select></div><div class="field"><label>Valor estimado (USD)</label><input name="estimated_value" type="number" min="0" step="0.01" value="${Number(lead.estimated_value||0)}"></div><div class="field"><label>Fuente</label><select name="source">${sources.map(x=>`<option ${lead.source===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Próxima acción</label><input name="next_action" value="${esc(lead.next_action||'')}"></div><div class="field"><label>Fecha de seguimiento</label><input name="next_action_at" type="datetime-local" value="${lead.next_action_at?new Date(new Date(lead.next_action_at).getTime()-new Date(lead.next_action_at).getTimezoneOffset()*60000).toISOString().slice(0,16):''}"></div><div class="field span-2"><label>Notas</label><textarea name="notes">${esc(lead.notes||'')}</textarea></div></div>`,{wide:true,onSubmit:async f=>{const phone=String(f.get('phone')||'').replace(/[^+\d]/g,'');const whatsapp=String(f.get('whatsapp')||'').replace(/[^+\d]/g,'');let website=String(f.get('website')||'').trim();if(website&&!/^https?:\/\//i.test(website))website='https://'+website;if(website){try{website=new URL(website).origin}catch{throw new Error('Ingresa un sitio web válido.')}}const patch={company_name:String(f.get('company_name')).trim(),contact_name:String(f.get('contact_name')).trim(),job_title:String(f.get('job_title')||'').trim()||null,phone:phone||null,whatsapp:whatsapp||null,email:String(f.get('email')||'').trim().toLowerCase()||null,website:website||null,city:String(f.get('city')||'').trim()||null,country:String(f.get('country')||'').trim()||null,service_id:f.get('service_id')||null,estimated_value:Number(f.get('estimated_value')||0),source:f.get('source'),next_action:String(f.get('next_action')||'').trim()||null,next_action_at:f.get('next_action_at')?new Date(f.get('next_action_at')).toISOString():null,notes:String(f.get('notes')||'').trim()||null};const {error}=await sb.from('leads').update(patch).eq('id',lead.id);if(error)throw error;await loadApp();notify('Oportunidad actualizada.')}})}
async function changeStage(lead,status){const existing=sales.find(s=>s.lead_id===lead.id);if(status==='won'&&!existing){modal('Confirmar oportunidad ganada',`<p class="subtext">Indica el valor final acordado. Los cobros y la comisión se registrarán después.</p><div class="field"><label>Valor final del proyecto (USD) *</label><input name="final_value" type="number" min="0.01" step="0.01" value="${Number(lead.estimated_value||0)}" required></div>`,{onSubmit:async f=>{const amount=Number(f.get('final_value'));if(amount<=0)throw new Error('El valor final debe ser mayor a cero.');try{const {error}=await sb.from('leads').update({status:'won',loss_reason:null}).eq('id',lead.id);if(error)throw error;const {error:se}=await sb.from('sales').insert({lead_id:lead.id,total_value:amount});if(se)throw se;await loadApp();notify('Venta ganada y valor final registrados.')}catch(e){await sb.from('leads').update({status:lead.status}).eq('id',lead.id);throw e}}});return}try{const patch={status};if(status==='lost')patch.loss_reason='Cierre marcado como perdido';else patch.loss_reason=null;const {error}=await sb.from('leads').update(patch).eq('id',lead.id);if(error)throw error;await loadApp();notify(`Etapa actualizada: ${labelStage(status)}.`)}catch(e){notify(errText(e),true);await loadApp()}}
function openActivity(lead){modal('Registrar actividad',`<div class="field"><label>Tipo</label><select name="type">${activityTypes.map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div class="field"><label>Asunto *</label><input name="subject" required maxlength="180" placeholder="Ej. Llamar para confirmar reunión"></div><div class="field"><label>Detalle</label><textarea name="body" maxlength="2000"></textarea></div><div class="field"><label>Próxima acción</label><input name="next_action" placeholder="Ej. Enviar propuesta"></div><div class="field"><label>Fecha de seguimiento</label><input name="next_action_at" type="datetime-local"></div>`,{onSubmit:async f=>{const nextAt=f.get('next_action_at')?new Date(f.get('next_action_at')).toISOString():null;const row={lead_id:lead.id,type:f.get('type'),subject:String(f.get('subject')).trim(),body:String(f.get('body')||'').trim()||null,due_at:f.get('type')==='task'?nextAt:null};if(f.get('type')==='task'&&!nextAt)throw new Error('Selecciona una fecha para el seguimiento.');const {error}=await sb.from('activities').insert(row);if(error)throw error;if(f.get('next_action')||f.get('next_action_at')){const {error:le}=await sb.from('leads').update({next_action:String(f.get('next_action')||'').trim()||null,next_action_at:nextAt}).eq('id',lead.id);if(le)throw le}await loadApp();notify('Actividad registrada.');openDetail(lead.id)}})}
function openPayment(sale){modal('Registrar cobro',`<div class="notice">Se registra un cobro real y la comisión se calcula automáticamente como el 40% del total recibido.</div><div class="field"><label>Monto recibido (USD) *</label><input name="amount" type="number" min="0.01" step="0.01" max="${Number(sale.pending_balance)}" required></div><div class="field"><label>Fecha de pago *</label><input name="paid_at" type="date" value="${new Date().toISOString().slice(0,10)}" required></div><div class="field"><label>Forma de pago</label><select name="payment_method"><option>Transferencia</option><option>Tarjeta</option><option>Efectivo</option><option>PayPal</option><option>Otro</option></select></div><div class="field"><label>Referencia / nota</label><input name="reference" maxlength="180"></div>`,{onSubmit:async f=>{const amount=Number(f.get('amount'));if(amount>Number(sale.pending_balance))throw new Error('El cobro supera el saldo pendiente.');const {error}=await sb.from('payments').insert({sale_id:sale.id,amount,paid_at:f.get('paid_at'),payment_method:f.get('payment_method'),reference:String(f.get('reference')||'').trim()||null});if(error)throw error;await loadApp();notify('Cobro confirmado y comisión recalculada.')}})}
function openCommissionPayment(id){const c=commissions.find(x=>x.id===id);modal('Registrar pago de comisión',`<div class="notice">Pendiente actual: <b>${money(c.pending_amount)}</b></div><div class="field"><label>Monto pagado (USD) *</label><input name="amount" type="number" min="0.01" step="0.01" max="${c.pending_amount}" required></div><div class="field"><label>Fecha de pago *</label><input name="paid_at" type="date" value="${new Date().toISOString().slice(0,10)}" required></div>`,{onSubmit:async f=>{const add=Number(f.get('amount'));if(add>Number(c.pending_amount))throw new Error('El pago supera la comisión pendiente.');const {error}=await sb.from('commissions').update({paid_amount:Number(c.paid_amount)+add,paid_at:f.get('paid_at')}).eq('id',id);if(error)throw error;await loadApp();notify('Pago de comisión registrado.')}})}
function openInvite(){modal('Crear cuenta de colaborador',`<p class="subtext">Define una contraseña inicial segura y compártela directamente con el colaborador.</p><div class="field"><label>Nombre completo *</label><input name="full_name" required maxlength="120"></div><div class="field"><label>Email *</label><input name="email" type="email" required></div><div class="field"><label>Teléfono</label><input name="phone" inputmode="tel"></div><div class="field"><label>Contraseña inicial (12 caracteres mínimo) *</label><input name="password" type="password" minlength="12" autocomplete="new-password" required></div>`,{submitLabel:'Crear cuenta',onSubmit:async f=>{const response=await fetch('/api/admin/users',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({full_name:String(f.get('full_name')).trim(),email:String(f.get('email')).trim().toLowerCase(),phone:String(f.get('phone')||'').trim(),password:String(f.get('password'))})});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error?.message||'No se pudo crear la cuenta.');await loadApp();notify('Cuenta creada.')}})}
async function toggleUser(id,isActive){try{const response=await fetch(`/api/admin/users/${encodeURIComponent(id)}`,{method:'PATCH',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({is_active:!isActive})});const result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error?.message||'No se pudo actualizar la cuenta.');await loadApp();notify(isActive?'Cuenta desactivada.':'Cuenta reactivada.')}catch(e){notify(errText(e),true)}}
async function archiveLead(lead){try{const {error}=await sb.from('leads').update({deleted_at:new Date().toISOString()}).eq('id',lead.id);if(error)throw error;await loadApp();notify('Oportunidad archivada.')}catch(e){notify(errText(e),true)}}
function openService(){modal('Agregar servicio',`<div class="field"><label>Nombre del servicio *</label><input name="name" required maxlength="120"></div><div class="field"><label>Precio referencial (USD)</label><input name="default_price" type="number" min="0" step="0.01" value="0"></div>`,{onSubmit:async f=>{const {error}=await sb.from('services').insert({name:String(f.get('name')).trim(),default_price:Number(f.get('default_price')||0)});if(error)throw error;await loadApp();notify('Servicio agregado.')}})}
function exportCsv(){const rows=visibleLeads();const cols=['Fecha','Empresa','Contacto','Teléfono','Email','Vendedor','Estado','Servicio','Valor estimado','Seguimiento','Fuente'];const data=rows.map(l=>[date(l.created_at),l.company_name,l.contact_name,l.phone,l.email,l.profiles?.full_name||person(l.owner_id),labelStage(l.status),l.services?.name,l.estimated_value,l.next_action_at?date(l.next_action_at):'',l.source]);const csv=[cols,...data].map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));link.download='nextwebec-oportunidades.csv';link.click();URL.revokeObjectURL(link.href)}
